static unsigned checks;
#define CHECK(x) do{checks++;if(!(x)){fprintf(stderr,"FAIL HTML source %d: %s\n",__LINE__,#x);exit(1);}}while(0)
static char *call(const SourcesConfig *cfg,const char *req,int expected){char *out=NULL;size_t n;FILE *f=open_memstream(&out,&n);CHECK(f);int rc=sources_dispatch(cfg,req,strlen(req),f);CHECK(!fclose(f));if(rc!=expected)fprintf(stderr,"response: %s\n",out);CHECK(rc==expected);Json j;CHECK(json_parse(&j,out,n));return out;}
static void error(const SourcesConfig *cfg,const char *req,const char *code){char *out=call(cfg,req,1);Json j;CHECK(json_parse(&j,out,strlen(out)));char *v=json_string(&j,json_get(&j,json_get(&j,0,"error"),"code"));CHECK(v&&!strcmp(v,code));free(v);free(out);}
static void write_file(const char *root,const char *name,const void *data,size_t n){char path[512];snprintf(path,sizeof(path),"%s/%s",root,name);int fd=open(path,O_CREAT|O_TRUNC|O_WRONLY,0600);CHECK(fd>=0);CHECK(write(fd,data,n)==(ssize_t)n);CHECK(!close(fd));}
static int cancelled(void *context){return *(int*)context;}
typedef struct {unsigned calls,stop_at;} Probe;
static int cancel_after_parse(void *context){Probe *p=context;return ++p->calls>=p->stop_at;}
static int expire_after_parse(void *context){Probe *p=context;if(++p->calls==4){struct timespec t={1,0};nanosleep(&t,NULL);}return 0;}
static unsigned cache_entries(const char *state){char path[600];snprintf(path,sizeof(path),"%s/sources.sqlite3",state);sqlite3 *db=NULL;sqlite3_stmt *stmt=NULL;CHECK(sqlite3_open(path,&db)==SQLITE_OK);CHECK(sqlite3_prepare_v2(db,"SELECT count(*) FROM evidence_cache",-1,&stmt,NULL)==SQLITE_OK);CHECK(sqlite3_step(stmt)==SQLITE_ROW);unsigned n=(unsigned)sqlite3_column_int(stmt,0);CHECK(!sqlite3_finalize(stmt));CHECK(!sqlite3_close(db));return n;}
static void error_no_cache(const SourcesConfig *cfg,const char *req,const char *code){unsigned before=cache_entries(cfg->state);error(cfg,req,code);CHECK(cache_entries(cfg->state)==before);}
