    snprintf(req,sizeof(req),"{\"contract_version\":1,\"op\":\"read_html\",\"source_id\":\"%s\",\"version\":\"%s\",\"start_byte\":0,\"end_byte\":999}",id,id);error(&cfg,req,"invalid_range");
    snprintf(req,sizeof(req),"{\"contract_version\":1,\"op\":\"read_html\",\"source_id\":\"%s\",\"version\":\"%s\",\"start_byte\":0,\"end_byte\":4,\"operation_id\":\"html-read\",\"parent_operation_id\":\"parent\",\"timeout_ms\":1000}",id,id);out=call(&cfg,req,0);CHECK(strstr(out,"html-read"));cfg.root=NULL;again=call(&cfg,req,0);CHECK(!strcmp(out,again));free(out);free(again);cfg.root=root;
