    snprintf(req,sizeof(req),"{\"contract_version\":1,\"op\":\"read_html\",\"source_id\":\"%s\",\"version\":\"%s\",\"start_byte\":7,\"end_byte\":10}",id,id);struct timespec received;CHECK(!clock_gettime(CLOCK_MONOTONIC,&received));Probe expired={0};SourcesConfig timed=cfg;timed.deadline_monotonic=(double)received.tv_sec+(double)received.tv_nsec/1e9+0.5;timed.cancelled=expire_after_parse;timed.cancellation=&expired;error_no_cache(&timed,req,"deadline_exceeded");CHECK(expired.calls==4);out=call(&cfg,req,0);free(out);
    char database[600];snprintf(database,sizeof(database),"%s/sources.sqlite3",state);sqlite3 *db=NULL;CHECK(sqlite3_open(database,&db)==SQLITE_OK);sqlite3_stmt *stmt=NULL;CHECK(sqlite3_prepare_v2(db,"UPDATE snapshots SET bytes=? WHERE id=?",-1,&stmt,NULL)==SQLITE_OK);CHECK(sqlite3_bind_blob(stmt,1,"damaged",7,SQLITE_STATIC)==SQLITE_OK);CHECK(sqlite3_bind_text(stmt,2,id,-1,SQLITE_STATIC)==SQLITE_OK);CHECK(sqlite3_step(stmt)==SQLITE_DONE);CHECK(!sqlite3_finalize(stmt));CHECK(!sqlite3_close(db));error(&cfg,req,"corrupt_snapshot");
    CHECK(sqlite3_open(database,&db)==SQLITE_OK);CHECK(sqlite3_prepare_v2(db,"UPDATE snapshots SET bytes=? WHERE id=?",-1,&stmt,NULL)==SQLITE_OK);CHECK(sqlite3_bind_blob(stmt,1,html,sizeof(html)-1,SQLITE_STATIC)==SQLITE_OK);CHECK(sqlite3_bind_text(stmt,2,id,-1,SQLITE_STATIC)==SQLITE_OK);CHECK(sqlite3_step(stmt)==SQLITE_DONE);CHECK(!sqlite3_finalize(stmt));CHECK(sqlite3_exec(db,"UPDATE evidence_cache SET digest='invalid'",NULL,NULL,NULL)==SQLITE_OK);CHECK(!sqlite3_close(db));error(&cfg,req,"corrupt_cache");
